package webui

import "encoding/base64"

// Icons as base64 (text-only tree). 32x32 PNG used for both /icon.png and favicon.
var (
	faviconBytes = mustB64(``)
	iconPNGBytes = faviconBytes
)

func mustB64(s string) []byte {
	b, err := base64.StdEncoding.DecodeString(s)
	if err != nil {
		return nil
	}
	return b
}
